fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target = width as usize;

    if orig_len >= target {
        // Original sequence already meets or exceeds target width, return unchanged
        orig
    } else {
        // Need to pad at the front with fillchar to reach target width
        let pad_len = target - orig_len;
        let mut result = Vec::with_capacity(target);
        // Add padding fill characters
        for _ in 0..pad_len {
            result.push(fillchar);
        }
        // Append the original sequence as suffix
        result.extend(orig);
        result
    }
}